479	// ---------------------------------------------------------------------------
480	// 运行时状态：配置快照 + 每接口独立序列
481	// ---------------------------------------------------------------------------
482	
483	function buildState(version: number, specs: readonly EndpointSpec[]): LiveState {
484	  const endpoints = new Map<string, LiveEndpoint>();
485	  for (const spec of specs) {
486	    endpoints.set(`${spec.method} ${spec.path}`, {
487	      key: `${spec.method} ${spec.path}`,
488	      responses: spec.responses,
489	      bodyRule: spec.bodyRule,
490	      cursor: 0,
491	    });
492	  }
493	  return { version, endpoints };
494	}
495	
496	// 同步预留下一项；同一事件循环内按“完整接收”事件的先后串行调用，天然保序。
497	// 末项之后持续返回末项，不跳项、不复用未到位置的项。
498	// 返回本次消费位置（0 起）与该项；末项复用时位置停在 length-1。
499	function reserveNext(endpoint: LiveEndpoint): { position: number; item: ResponseSpec } {
500	  const last = endpoint.responses.length - 1;
501	  const position = endpoint.cursor < last ? endpoint.cursor : last;
502	  if (endpoint.cursor < last) {
503	    endpoint.cursor += 1;
504	  }
505	  return { position, item: endpoint.responses[position] };
506	}
