508	// ---------------------------------------------------------------------------
509	// 进程内请求记录
510	// ---------------------------------------------------------------------------
511	//
512	// 仅记录管理范围之外、完整接收且未超过正文上限的请求（场景响应、400、404）。
513	// 未收完整即断开或超出上限不创建记录、不消费序列。
514	// 编号按“完整接收”顺序在进程内单调递增，与接口消费位置是两回事；
515	// 清空与成功/失败重载都保留编号序列，编号不复用。记录只存在内存中，不写文件。
516	
517	// 写出生命周期（仅指服务器侧写出，不表示客户端已收到）：
518	//   pending     —— 已完整接收、计划响应待发送（延迟期间即可查到）
519	//   sent        —— 服务器已完成响应写出；此后连接正常关闭不再改变状态
520	//   interrupted —— 写出完成前连接断开或写入/发送失败
521	type DeliveryStatus = 'pending' | 'sent' | 'interrupted';
522	
523	// 计划响应：场景响应为 'scene'，400/404 等框架响应为 'framework'
524	interface PlannedResponseSnapshot {
525	  readonly kind: 'scene' | 'framework';
526	  readonly status: number;
527	  // 应用层响应头：配置头/框架头 + 服务器填写的准确版本头，不含传输层自动头
528	  readonly headers: { readonly [name: string]: string };
529	  // 配置/框架给出的响应正文文本（不含 HTTP 层按 Content-Length 等补出的字节）
530	  readonly body: string;
531	}
532	
533	interface RequestRecord {
534	  readonly id: number;
535	  readonly receivedAt: string;
536	  readonly request: {
537	    readonly method: string;
538	    // 含查询串的原始请求目标
539	    readonly target: string;
540	    readonly path: string;
541	    // 原始请求头：按在线顺序成对保留，名称大小写与重复头均不折叠
542	    readonly rawHeaders: readonly string[];
543	    readonly bodyBytes: number;
544	    // 正文原始字节的无损表示：合法 UTF-8 时以文本给出，否则以 base64 给出
545	    readonly body: { readonly encoding: 'utf-8' | 'base64'; readonly content: string };
546	  };
547	  // 完整接收那一刻选用的配置版本；在途请求的结论不随之后的 reload 改变
548	  configVersion: number;
549	  // matched=false：未匹配（404），不消费任何序列
550	  matched: boolean;
551	  endpoint: string | null;
552	  // null 表示未做正文校验（GET/未声明规则）；true=通过，false=拒绝并返回 400
553	  bodyValidationPassed: boolean | null;
554	  // 400 时实际返回的差异报告（与响应正文中的 JSON 同一份数据）
555	  bodyRejection: BodyReport | null;
556	  // 场景请求在序列中的消费位置（0 起）；400/404 没有消费位置，记为 null
557	  sequencePosition: number | null;
558	  sequenceLength: number | null;
559	  plannedResponse: PlannedResponseSnapshot | null;
560	  delivery: DeliveryStatus;
561	}
562	
563	// 已清空记录的投递回调落到空集合上：不取消响应，旧请求之后完成也不得重新出现。
564	class RequestLog {
565	  private records: RequestRecord[] = [];
566	  // 仍可能被投递事件更新的记录 id 集合（清空后旧 id 不在其中）
567	  private readonly live = new Map<number, RequestRecord>();
568	  private nextId = 1;
569	
570	  create(entry: {
571	    method: string;
572	    target: string;
573	    path: string;
574	    rawHeaders: readonly string[];
575	    body: Buffer;
576	    configVersion: number;
577	  }): RequestRecord {
578	    const id = this.nextId;
579	    this.nextId += 1;
580	    const record: RequestRecord = {
581	      id,
582	      receivedAt: new Date().toISOString(),
583	      request: {
584	        method: entry.method,
585	        target: entry.target,
586	        path: entry.path,
587	        rawHeaders: entry.rawHeaders,
588	        bodyBytes: entry.body.byteLength,
589	        body: encodeBodyLosslessly(entry.body),
590	      },
591	      configVersion: entry.configVersion,
592	      matched: false,
593	      endpoint: null,
594	      bodyValidationPassed: null,
595	      bodyRejection: null,
596	      sequencePosition: null,
597	      sequenceLength: null,
598	      plannedResponse: null,
599	      delivery: 'pending',
600	    };
601	    this.records.push(record);
602	    this.live.set(id, record);
603	    return record;
604	  }
605	
606	  // 写出完成；对已清空（不再存活）的记录是 no-op
607	  markDelivered(id: number, status: DeliveryStatus): void {
608	    const record = this.live.get(id);
609	    if (!record) {
610	      return;
611	    }
612	    // 一旦完成写出即为终态：之后的连接正常关闭不得回退为 interrupted
613	    if (record.delivery === 'sent') {
614	      return;
615	    }
616	    record.delivery = status;
617	  }
618	
619	  // 调用时一致快照：拷贝当前存活记录，不推进任何序列
620	  snapshot(): readonly RequestRecord[] {
621	    return [...this.records];
622	  }
623	
624	  // 清空一次移除当时全部记录（含待发送项）；不取消响应、不改配置/版本/序列。
625	  // 清空前已完整接收的请求随后完成或失败都不再出现。
626	  clear(): number {
627	    const removed = this.records.length;
628	    this.records = [];
629	    this.live.clear();
630	    return removed;
631	  }
632	}
633	
634	// 原始正文字节的无损文本表示：先尝试严格 UTF-8；失败则用 base64 承载任意字节。
635	// 记录的是原始字节而非解析后的 JSON，避免任何信息损失。
636	// ignoreBOM：开头 BOM（EF BB BF）必须保留在文本中（默认行为会将其丢弃），
637	// 否则文本重新编码回不去原始字节，快照就不再无损。
638	function encodeBodyLosslessly(body: Buffer): { encoding: 'utf-8' | 'base64'; content: string } {
639	  try {
640	    const text = new TextDecoder('utf-8', { fatal: true, ignoreBOM: true }).decode(body);
641	    return { encoding: 'utf-8', content: text };
642	  } catch {
643	    return { encoding: 'base64', content: body.toString('base64') };
644	  }
645	}
646	
647	// ---------------------------------------------------------------------------
648	// 请求正文校验：媒体类型 → UTF-8 JSON 解析 → 结构比对
649	// ---------------------------------------------------------------------------
650	
651	interface StructureProblem {
652	  readonly pointer: string;
653	  readonly expected: string;
654	  readonly actual: string;
655	}
656	
657	interface BodyReport {
658	  readonly error: 'invalid_request_body';
659	  readonly stage: 'parse' | 'structure';
660	  readonly message: string;
661	  readonly problems: readonly StructureProblem[];
662	}
663	
664	function parseFailure(message: string): BodyReport {
665	  return { error: 'invalid_request_body', stage: 'parse', message, problems: [] };
666	}
667	
668	function jsonTypeOf(value: unknown): string {
669	  if (value === null) {
670	    return 'null';
671	  }
672	  if (Array.isArray(value)) {
673	    return 'array';
674	  }
675	  return typeof value;
676	}
677	
678	// RFC 6901 JSON Pointer 段转义：~ -> ~0，/ -> ~1
679	function escapePointerSegment(segment: string): string {
680	  return segment.replace(/~/g, '~0').replace(/\//g, '~1');
681	}
682	
683	// 枚举差异的期望描述：列全候选值（JSON 形式，数字 0 与 -0 都写作 0）
684	function enumExpectedText(enumValues: readonly EnumValue[]): string {
685	  return `枚举 ${JSON.stringify(enumValues)} 之一`;
686	}
687	
688	// 结构比对：父节点类型不符时只报告该节点，不再深入制造子节点错误；
689	// 字段缺失（hasOwnProperty 为假）与合法的 JSON null 分开判断。
690	// 可空规则：null 被接受时不产生任何子节点差异；非 null 继续检查全部原约束。
691	// 枚举规则：接受集合为“类型及可空集合”与枚举集合的交集——可空不越过枚举
692	// （null 须列入枚举才被接受）；类型错误只报类型差异，不重复报枚举差异。
693	function checkRule(
694	  rule: BodyRule,
695	  value: unknown,
696	  pointer: string,
697	  problems: StructureProblem[],
698	): void {
699	  if (value === null && rule.nullable) {
700	    // 可空不越过枚举：有枚举时 null 仍须在候选集合中
701	    if (rule.kind === 'object' || rule.kind === 'array') {
702	      return;
703	    }
704	    if (rule.enum === undefined || rule.enum.includes(null)) {
705	      return;
706	    }
707	    problems.push({ pointer, expected: enumExpectedText(rule.enum), actual: 'null' });
708	    return;
709	  }
710	  switch (rule.kind) {
711	    case 'string':
712	    case 'boolean':
713	      if (typeof value !== rule.kind) {
714	        problems.push({ pointer, expected: rule.kind, actual: jsonTypeOf(value) });
715	        return;
716	      }
717	      break;
718	    case 'null':
719	      if (value !== null) {
720	        problems.push({ pointer, expected: 'null', actual: jsonTypeOf(value) });
721	      }
722	      return;
723	    case 'number':
724	      if (typeof value !== 'number' || !Number.isFinite(value)) {
725	        problems.push({ pointer, expected: 'number', actual: jsonTypeOf(value) });
726	        return;
727	      }
728	      break;
729	    case 'integer':
730	      if (!Number.isInteger(value)) {
731	        problems.push({ pointer, expected: 'integer', actual: jsonTypeOf(value) });
732	        return;
733	      }
734	      break;
735	    case 'array': {
736	      if (!Array.isArray(value)) {
737	        problems.push({ pointer, expected: 'array', actual: jsonTypeOf(value) });
738	        return;
739	      }
740	      for (let i = 0; i < value.length; i += 1) {
741	        checkRule(rule.items, value[i], `${pointer}/${i}`, problems);
742	      }
743	      return;
744	    }
745	    case 'object': {
746	      if (!isPlainObject(value)) {
747	        problems.push({ pointer, expected: 'object', actual: jsonTypeOf(value) });
748	        return;
749	      }
750	      for (const [name, field] of rule.fields) {
751	        const childPointer = `${pointer}/${escapePointerSegment(name)}`;
752	        if (!Object.prototype.hasOwnProperty.call(value, name)) {
753	          if (field.required) {
754	            problems.push({
755	              pointer: childPointer,
756	              expected: `${field.rule.kind}（必填字段）`,
757	              actual: 'missing',
758	            });
759	          }
760	        } else {
761	          checkRule(field.rule, value[name], childPointer, problems);
762	        }
763	      }
764	      if (!rule.additionalProperties) {
765	        for (const key of Object.keys(value)) {
766	          if (!rule.fields.has(key)) {
767	            problems.push({
768	              pointer: `${pointer}/${escapePointerSegment(key)}`,
769	              expected: '未声明的字段（不允许）',
770	              actual: jsonTypeOf(value[key]),
771	            });
772	          }
773	        }
774	      }
775	      return;
776	    }
777	  }
778	  // 标量枚举：类型检查已通过才核对候选集合（类型错误不重复报枚举错误）；
779	  // 数字按数值相等（0 与 -0 等价），不做类型转换
780	  if (rule.enum !== undefined && !rule.enum.includes(value as EnumValue)) {
781	    problems.push({
782	      pointer,
783	      expected: enumExpectedText(rule.enum),
784	      actual: JSON.stringify(value),
785	    });
786	  }
787	}
788	
789	// 返回 null 表示校验通过；否则为可直接序列化的 400 差异报告。
790	// contentType 为在线顺序第一项 Content-Type 头值（在线：Node 对重复
791	// content-type 只保留首项；离线 verify：取 rawHeaders 中首个同名头）。
792	// 正文解码与 JSON 解析不重写原文：BOM 与空白按 UTF-8 解码的默认规则处理，
793	// 在线与离线对同一组字节给出同一结论。
794	function validateBodyWithContentType(
795	  contentType: string | undefined,
796	  body: Buffer,
797	  rule: BodyRule,
798	): BodyReport | null {
799	  const mediaType =
800	    typeof contentType === 'string' ? contentType.split(';', 1)[0].trim().toLowerCase() : '';
801	  if (mediaType !== 'application/json') {
802	    return parseFailure(
803	      typeof contentType === 'string'
804	        ? `媒体类型不符：期望 application/json（可带参数、忽略大小写），收到 "${contentType}"`
805	        : '缺少 Content-Type 头：期望 application/json（可带参数、忽略大小写）',
806	    );
807	  }
808	
809	  if (body.length === 0) {
810	    return parseFailure('请求正文为空，无法解析为 JSON');
811	  }
812	
813	  let text: string;
814	  try {
815	    text = new TextDecoder('utf-8', { fatal: true }).decode(body);
816	  } catch {
817	    return parseFailure('请求正文不是合法的 UTF-8 编码');
818	  }
819	
820	  let parsed: unknown;
821	  try {
822	    parsed = JSON.parse(text);
823	  } catch (e) {
824	    return parseFailure(`请求正文不是合法 JSON：${describeError(e)}`);
825	  }
826	
827	  const problems: StructureProblem[] = [];
828	  checkRule(rule, parsed, '', problems);
829	  if (problems.length > 0) {
830	    return {
831	      error: 'invalid_request_body',
832	      stage: 'structure',
833	      message: `请求正文与接口约定存在 ${problems.length} 处差异`,
834	      problems,
835	    };
836	  }
837	  return null;
838	}
839	
840	// ---------------------------------------------------------------------------
841	// 文件读取与（重新）加载：读、解析、校验全部通过后才一次性替换
842	// ---------------------------------------------------------------------------
843	
844	function describeError(e: unknown): string {
845	  return e instanceof Error ? e.message : String(e);
846	}
847	
848	// 读取 -> 解析 -> 严格校验；任何一步失败都抛出含文件路径与可定位原因的错误
849	async function loadSpecsFromFile(configPath: string): Promise<EndpointSpec[]> {
850	  let text: string;
851	  try {
852	    text = await readFile(configPath, 'utf8');
853	  } catch (e) {
854	    throw new Error(`读取配置文件 ${configPath} 失败：${describeError(e)}`);
855	  }
856	
857	  let raw: unknown;
858	  try {
859	    raw = JSON.parse(text);
860	  } catch (e) {
861	    throw new Error(`配置文件 ${configPath} 不是合法 JSON：${describeError(e)}`);
862	  }
863	
864	  try {
865	    return validateConfig(raw);
866	  } catch (e) {
867	    throw new Error(`配置文件 ${configPath} 校验失败：${describeError(e)}`);
868	  }
869	}
870	
871	async function loadStateFromFile(configPath: string, version: number): Promise<LiveState> {
872	  return buildState(version, await loadSpecsFromFile(configPath));
873	}
