875	// ---------------------------------------------------------------------------
876	// 离线兼容报告（compare 子命令）
877	// ---------------------------------------------------------------------------
878	//
879	// 兼容方向固定为 旧 -> 新：旧配置能按“方法 + 字面路径”匹配且通过正文检查的
880	// 每一种请求，在新配置中仍须匹配并通过。只比较接口存在性与请求接受条件；
881	// 响应状态/头/正文/延迟与序列差异不影响结论。
882	//
883	// 双方都配置 requestBody 时，比较的是“规则所接受 JSON 值的集合包含关系”
884	// L(旧规则) ⊆ L(新规则)，而不是文本比较或抽样请求；每个不兼容点都附一份
885	// 具体反例（旧规则接受、新规则拒绝的完整 JSON 值）。
886	
887	interface ReportReason {
888	  // 正文差异：RFC 6901 指针（根为 ""）；接口级原因（如接口删除）无此字段
889	  readonly pointer?: string;
890	  readonly message: string;
891	}
892	
893	interface ReportExample {
894	  readonly method: HttpMethod;
895	  readonly path: string;
896	  readonly headers: { readonly [name: string]: string };
897	  readonly body: string;
898	}
899	
900	interface EndpointReport {
901	  readonly method: HttpMethod;
902	  readonly path: string;
903	  readonly compatible: boolean;
904	  readonly reasons: readonly ReportReason[];
905	  readonly example?: ReportExample;
906	}
907	
908	interface CompareReport {
909	  readonly compatible: boolean;
910	  readonly oldFile: string;
911	  readonly newFile: string;
912	  readonly endpoints: readonly EndpointReport[];
913	}
914	
915	interface BodyViolation {
916	  readonly pointer: string;
917	  readonly message: string;
918	  // 完整请求正文反例：被旧规则接受、被新规则拒绝
919	  readonly value: unknown;
920	}
921	
922	// 生成被规则接受的最小 JSON 值：object 只含必填字段，array 取空数组；
923	// 枚举节点任选一候选（优先非 null 项——“类型收紧”反例需要非 null 样本）。
924	// 字段名可能是 "" 或 "__proto__"，一律用无原型对象按自有字段构造。
925	function sampleValue(rule: BodyRule): unknown {
926	  if (rule.kind !== 'object' && rule.kind !== 'array' && rule.enum !== undefined) {
927	    const nonNull = rule.enum.find((v) => v !== null);
928	    return nonNull === undefined ? null : nonNull;
929	  }
930	  switch (rule.kind) {
931	    case 'string':
932	      return 'contractlab';
933	    case 'number':
934	    case 'integer':
935	      return 0;
936	    case 'boolean':
937	      return false;
938	    case 'null':
939	      return null;
940	    case 'array':
941	      return [];
942	    case 'object': {
943	      const obj: Record<string, unknown> = Object.create(null);
944	      for (const [name, field] of rule.fields) {
945	        if (field.required) {
946	          obj[name] = sampleValue(field.rule);
947	        }
948	      }
949	      return obj;
950	    }
951	  }
952	}
953	
954	// 规则是否接受 null：type:null 或 nullable:true；有枚举时 null 还须列入候选
955	// （可空不越过枚举）。object / array 节点没有枚举。
956	function ruleAcceptsNullValue(rule: BodyRule): boolean {
