1095	        out.push({
1096	          pointer,
1097	          value,
1098	          message: `枚举收紧：旧规则接受的枚举值 ${JSON.stringify(value)} 不被新规则（${scalarRuleLabel(newRule)}）接受`,
1099	        });
1100	      }
1101	    }
1102	    return;
1103	  }
1104	
1105	  if (newRule.enum !== undefined) {
1106	    // 旧规则接受整个类型集合，新规则只接受枚举候选
1107	    if (oldRule.kind === 'boolean') {
1108	      for (const value of [false, true]) {
1109	        if (!scalarValueAccepted(newRule, value)) {
1110	          out.push({
1111	            pointer,
1112	            value,
1113	            message: `新规则引入枚举限制（${enumExpectedText(newRule.enum)}），旧规则允许的值 ${JSON.stringify(value)} 不在候选中`,
1114	          });
1115	        }
1116	      }
1117	      return;
1118	    }
1119	    if (oldRule.kind === 'string' || oldRule.kind === 'number' || oldRule.kind === 'integer') {
1120	      // 类型取值无限而枚举有限：构造旧规则接受、但不在新枚举中的见证值
1121	      const witness = freshValueOutsideEnum(oldRule.kind, newRule.enum);
1122	      out.push({
1123	        pointer,
1124	        value: witness,
1125	        message: `新规则引入枚举限制（${enumExpectedText(newRule.enum)}），旧规则允许的值 ${JSON.stringify(witness)} 不在候选中`,
1126	      });
1127	      return;
1128	    }
1129	    return; // oldRule.kind === 'null' 不会到达（调用方已处理）
1130	  }
1131	
1132	  // 双方均无枚举：仅同名兼容，外加 integer 放宽为 number
1133	  const compatible =
1134	    oldRule.kind === newRule.kind || (oldRule.kind === 'integer' && newRule.kind === 'number');
1135	  if (!compatible) {
1136	    // number -> integer 时样本必须是非整数，否则 0 会被新规则接受
1137	    const value =
1138	      oldRule.kind === 'number' && newRule.kind === 'integer' ? 0.5 : sampleValue(oldRule);
1139	    out.push({
1140	      pointer,
1141	      value,
1142	      message: `类型收紧：旧规则接受 ${kindLabel(oldRule)}，新规则只接受 ${newRule.kind}`,
1143	    });
1144	  }
