1153	// 都精确判定；可空不越过枚举（null 须列入枚举才算被接受）。
1154	function collectViolations(
1155	  oldRule: BodyRule,
1156	  newRule: BodyRule,
1157	  pointer: string,
1158	  out: BodyViolation[],
1159	): void {
