1168	    return;
1169	  }
1170	  // 枚举仅含 null 项的旧规则同样只接受 null：可比较的只有 null，上面已处理
1171	  if (!hasNonNullAcceptedValues(oldRule)) {
1172	    return;
1173	  }
1174	  // 新规则只接受 null：旧规则的任意非 null 样本都是反例
1175	  if (newRule.kind === 'null') {
1176	    out.push({
1177	      pointer,
1178	      value: sampleValue(oldRule),
1179	      message: `类型收紧：旧规则接受 ${kindLabel(oldRule)}，新规则只接受 null`,
1180	    });
1181	    return;
1182	  }
1183	
1184	  if (newRule.kind !== 'object' && newRule.kind !== 'array') {
1185	    // 新规则是标量：旧规则为对象/数组时任何样本都被拒绝
