1188	        pointer,
1189	        value: sampleValue(oldRule),
1190	        message: `类型收紧：旧规则接受 ${kindLabel(oldRule)}，新规则只接受 ${newRule.kind}`,
1191	      });
1192	      return;
1193	    }
1194	    collectScalarViolations(oldRule, newRule, pointer, out);
