1196	  }
1197	
1198	  if (newRule.kind === 'array') {
1199	    if (oldRule.kind !== 'array') {
1200	      out.push({
1201	        pointer,
1202	        value: sampleValue(oldRule),
1203	        message: `类型收紧：旧规则接受 ${kindLabel(oldRule)}，新规则只接受 array`,
1204	      });
