1212	    }
1213	    return;
1214	  }
1215	
1216	  // newRule.kind === 'object'
1217	  if (oldRule.kind !== 'object') {
1218	    out.push({
1219	      pointer,
1220	      value: sampleValue(oldRule),
1221	      message: `类型收紧：旧规则接受 ${kindLabel(oldRule)}，新规则只接受 object`,
1222	    });
1223	    return;
1224	  }
1225	
1226	  // (a) 新规则的必填字段必须被旧规则保证存在（旧规则未声明或仅可选即存在反例）
1227	  for (const [name, newField] of newRule.fields) {
1228	    if (!newField.required) {
1229	      continue;
1230	    }
1231	    const oldField = oldRule.fields.get(name);
1232	    if (!oldField || !oldField.required) {
1233	      out.push({
1234	        pointer: `${pointer}/${escapePointerSegment(name)}`,
1235	        // 旧规则的最小样本不含可缺省/未声明字段，恰为反例
1236	        value: sampleValue(oldRule),
1237	        message: `新规则要求必填字段 ${JSON.stringify(name)}，旧规则允许缺省该字段`,
1238	      });
1239	    }
1240	  }
1241	
1242	  // (b) 旧规则声明的字段，在新规则下仍须被接受
1243	  for (const [name, oldField] of oldRule.fields) {
1244	    const childPointer = `${pointer}/${escapePointerSegment(name)}`;
1245	    const newField = newRule.fields.get(name);
1246	    if (!newField) {
1247	      if (!newRule.additionalProperties) {
