1256	    const sub: BodyViolation[] = [];
1257	    collectViolations(oldField.rule, newField.rule, childPointer, sub);
1258	    for (const s of sub) {
1259	      out.push({
1260	        pointer: s.pointer,
1261	        message: s.message,
1262	        value: sampleObjectWith(oldRule, name, s.value),
1263	      });
1264	    }
1265	  }
1266	
