1292	// 旧接口被旧配置接受的一个请求样本（用于“接口已删除”反例）
1293	function acceptedRequestExample(endpoint: EndpointSpec): ReportExample {
1294	  if (endpoint.bodyRule) {
1295	    return {
1296	      method: endpoint.method,
1297	      path: endpoint.path,
1298	      headers: { 'Content-Type': 'application/json' },
1299	      body: JSON.stringify(sampleValue(endpoint.bodyRule)),
1300	    };
1301	  }
1302	  return { method: endpoint.method, path: endpoint.path, headers: {}, body: '' };
1303	}
