1363	function compareConfigs(
1364	  oldSpecs: readonly EndpointSpec[],
1365	  newSpecs: readonly EndpointSpec[],
1366	  oldFile: string,
1367	  newFile: string,
1368	): CompareReport {
1369	  const newByKey = new Map<string, EndpointSpec>();
1370	  for (const spec of newSpecs) {
1371	    newByKey.set(`${spec.method} ${spec.path}`, spec);
1372	  }
1373	  const endpoints = oldSpecs.map((spec) =>
1374	    compareEndpoint(spec, newByKey.get(`${spec.method} ${spec.path}`)),
1375	  );
1376	  return {
1377	    compatible: endpoints.every((ep) => ep.compatible),
1378	    oldFile,
1379	    newFile,
1380	    endpoints,
1381	  };
1382	}
