1547	// JSON Pointer 段反转义：~1 -> /，~0 -> ~；其余 “~” 用法非法
1548	function unescapeRefSegment(
1549	  segment: string,
1550	  ref: string,
1551	  ctx: ImportCtx,
1552	  where: string,
1553	): string {
1554	  let out = '';
1555	  for (let i = 0; i < segment.length; i += 1) {
1556	    const ch = segment[i];
1557	    if (ch === '~') {
1558	      const next = segment[i + 1];
1559	      if (next === '0') {
1560	        out += '~';
1561	        i += 1;
1562	      } else if (next === '1') {
1563	        out += '/';
1564	        i += 1;
1565	      } else {
1566	        importFail(ctx, where, `$ref "${ref}" 含非法的 "~" 转义（仅支持 ~0 与 ~1）`);
1567	      }
1568	    } else {
1569	      out += ch;
1570	    }
1571	  }
1572	  return out;
1573	}
