1578	  node: Record<string, unknown>,
1579	  ctx: ImportCtx,
1580	  where: string,
1581	  refChain: readonly string[],
1582	): { target: unknown; where: string; refChain: readonly string[] } | null {
1583	  if (!hasOwnKey(node, '$ref')) {
1584	    return null;
1585	  }
1586	  if (Object.keys(node).length !== 1) {
1587	    importFail(ctx, where, '含 $ref 的引用节点不得包含其他字段（只允许 "$ref"）');
1588	  }
1589	  const ref = node.$ref;
1590	  if (typeof ref !== 'string' || !ref.startsWith('#')) {
1591	    importFail(
1592	      ctx,
1593	      where,
1594	      `仅支持本文件内 $ref（以 "#" 开头的 JSON Pointer），收到 ${JSON.stringify(ref)}`,
1595	    );
1596	  }
1597	  if (refChain.includes(ref as string)) {
1598	    importFail(ctx, where, `循环 $ref 引用：${[...refChain, ref].join(' -> ')}`);
