      const o = objs[i];
      const sub = o.props.get(name);
      if (sub !== undefined) {
        declarers.push({ rule: sub, loc: `${flat[i].loc}.properties[${JSON.stringify(name)}]` });
      } else if (!o.addl && forbiddener === undefined) {
        forbiddener = flat[i];
