2628	function verifyRequests(
2629	  requests: readonly SnapshotRequest[],
2630	  specs: readonly EndpointSpec[],
2631	  requestsFile: string,
2632	  configFile: string,
2633	): VerifyReport {
2634	  const byKey = new Map<string, EndpointSpec>();
2635	  for (const spec of specs) {
2636	    byKey.set(`${spec.method} ${spec.path}`, spec);
2637	  }
2638	  const results = requests.map((req): VerifyResultEntry => {
2639	    const endpoint =
2640	      req.method === 'GET' || req.method === 'POST'
2641	        ? byKey.get(`${req.method} ${req.path}`)
2642	        : undefined;
2643	    if (!endpoint) {
2644	      return { id: req.id, outcome: 'unmatched', endpoint: null };
2645	    }
2646	    const key = `${endpoint.method} ${endpoint.path}`;
2647	    if (endpoint.bodyRule) {
2648	      const rejection = validateBodyWithContentType(req.contentType, req.body, endpoint.bodyRule);
2649	      if (rejection) {
2650	        return { id: req.id, outcome: 'rejected', endpoint: key, rejection };
2651	      }
2652	      return { id: req.id, outcome: 'passed', endpoint: key };
2653	    }
2654	    return { id: req.id, outcome: 'no_body_check', endpoint: key };
2655	  });
2656	  const accepted = results.filter(
2657	    (r) => r.outcome === 'passed' || r.outcome === 'no_body_check',
2658	  ).length;
2659	  return {
2660	    requestsFile,
2661	    configFile,
2662	    total: results.length,
2663	    accepted,
2664	    rejected: results.length - accepted,
2665	    results,
2666	  };
2667	}
