2669	async function runVerify(requestsArg: string, configArg: string): Promise<never> {
2670	  const requestsFile = path.resolve(requestsArg);
2671	  const configFile = path.resolve(configArg);
2672	
2673	  const attemptSnapshot = async (): Promise<{ requests?: SnapshotRequest[]; error?: string }> => {
2674	    try {
2675	      return { requests: await loadSnapshotFromFile(requestsFile) };
2676	    } catch (e) {
2677	      return { error: describeError(e) };
2678	    }
2679	  };
2680	  const attemptSpecs = async (): Promise<{ specs?: EndpointSpec[]; error?: string }> => {
2681	    try {
2682	      return { specs: await loadSpecsFromFile(configFile) };
2683	    } catch (e) {
2684	      return { error: describeError(e) };
2685	    }
2686	  };
2687	
2688	  // 两份输入都完整经历 读取 -> 解析 -> 严格校验；任一失败则不输出任何报告
2689	  const [snapResult, specResult] = await Promise.all([attemptSnapshot(), attemptSpecs()]);
2690	  let failed = false;
2691	  if (snapResult.error !== undefined) {
2692	    process.stderr.write(`${APP_NAME}: verify 请求快照：${snapResult.error}\n`);
2693	    failed = true;
2694	  }
2695	  if (specResult.error !== undefined) {
2696	    process.stderr.write(`${APP_NAME}: verify 场景配置：${specResult.error}\n`);
2697	    failed = true;
2698	  }
2699	  if (failed) {
2700	    process.exit(2);
2701	  }
2702	
2703	  const report = verifyRequests(
2704	    snapResult.requests as SnapshotRequest[],
2705	    specResult.specs as EndpointSpec[],
2706	    requestsFile,
2707	    configFile,
2708	  );
2709	  process.stdout.write(`${JSON.stringify(report, null, 2)}\n`);
2710	  process.exit(report.rejected === 0 ? 0 : 1);
2711	}
