2751	// 一条待重放的请求：共享快照校验之上再经重放专用校验
2752	interface ReplayRequest {
2753	  readonly id: number;
2754	  readonly method: 'GET' | 'POST';
2755	  // 原样发送的请求目标（含查询串与百分号编码，不归一化）
2756	  readonly target: string;
2757	  // 过滤后的业务头：名称大小写、重复项与在线顺序原样保留
2758	  readonly headers: readonly [string, string][];
2759	  readonly body: Buffer;
2760	  readonly plannedStatus: number;
2761	  readonly plannedBody: string;
2762	}
