2764	// target 须为以 "/" 开头的合法 HTTP 请求目标：不含空白与控制字符，
2765	// 且每个字符都在 Latin-1 内（与 Node 客户端对 path 的接受范围一致）
2766	function validateReplayTarget(target: string, where: string): void {
2767	  if (target.length === 0 || !target.startsWith('/')) {
2768	    snapshotFail(where, `必须是以 "/" 开头的 HTTP 请求目标，收到 ${JSON.stringify(target)}`);
2769	  }
2770	  for (const ch of target) {
2771	    const code = ch.charCodeAt(0);
2772	    if (code <= 0x20 || code === 0x7f) {
2773	      snapshotFail(where, `含空白或控制字符，不是合法的 HTTP 请求目标：${JSON.stringify(target)}`);
2774	    }
2775	    if (code > 0xff) {
2776	      snapshotFail(where, `含 Latin-1 之外的字符，无法作为 HTTP 请求目标发送：${JSON.stringify(target)}`);
2777	    }
2778	  }
2779	}
