2781	// 过滤并校验待发送的业务头：剥离 Host/Expect/逐跳/分帧头（含 Connection
2782	// 指名的头），其余按原顺序、大小写与重复项保留；保留的头名称与值必须可发送。
2783	function filterReplayHeaders(
2784	  rawHeaders: readonly string[],
2785	  where: string,
2786	): [string, string][] {
2787	  const connectionNamed = new Set<string>();
2788	  for (let j = 0; j + 1 < rawHeaders.length; j += 2) {
2789	    if ((rawHeaders[j] as string).toLowerCase() === 'connection') {
2790	      for (const token of (rawHeaders[j + 1] as string).split(',')) {
2791	        const name = token.trim().toLowerCase();
2792	        if (name !== '') {
2793	          connectionNamed.add(name);
2794	        }
2795	      }
2796	    }
2797	  }
2798	  const out: [string, string][] = [];
2799	  for (let j = 0; j + 1 < rawHeaders.length; j += 2) {
2800	    const name = rawHeaders[j] as string;
2801	    const value = rawHeaders[j + 1] as string;
2802	    const lower = name.toLowerCase();
2803	    if (REPLAY_STRIP_HEADERS.has(lower) || connectionNamed.has(lower)) {
2804	      continue;
2805	    }
2806	    if (!HEADER_NAME_RE.test(name)) {
2807	      snapshotFail(`${where}[${j}]`, `不是可发送的 HTTP 头名称：${JSON.stringify(name)}`);
2808	    }
2809	    for (let k = 0; k < value.length; k += 1) {
2810	      const code = value.charCodeAt(k);
2811	      // 与响应头同一规则：允许水平制表符；拒绝换行及其余控制字符；仅 Latin-1
2812	      if ((code <= 0x1f && code !== 0x09) || code === 0x7f || code > 0xff) {
2813	        snapshotFail(
2814	          `${where}[${j + 1}]`,
2815	          `头 ${JSON.stringify(name)} 的值不得包含换行或其他控制字符，且只能使用 Latin-1 字符`,
2816	        );
2817	      }
2818	    }
2819	    out.push([name, value]);
2820	  }
2821	  return out;
2822	}
