2827	  const base = parseSnapshotRecord(raw, index, seen);
2828	
2829	  if (base.method !== 'GET' && base.method !== 'POST') {
2830	    snapshotFail(
2831	      `${where}.request.method`,
2832	      `仅支持重放 GET/POST，收到 ${JSON.stringify(base.method)}`,
2833	    );
2834	  }
2835	  validateReplayTarget(base.target, `${where}.request.target`);
2836	  if (base.path === ADMIN_BASE || base.path.startsWith(ADMIN_PREFIX)) {
