2905	interface ReplayResponse {
2906	  readonly status: number;
2907	  readonly body: Buffer;
2908	}
2909	
2910	type ReplayExchange =
2911	  | { readonly ok: true; readonly response: ReplayResponse }
2912	  | { readonly ok: false; readonly reason: string };
2913	
2914	// 重放单条请求：独立连接、只尝试一次、不跟随重定向；总超时自开始连接覆盖
2915	// 完整收发，不因持续来数据而延长。通信失败时关闭连接并返回原因。
2916	function replayOne(port: number, request: ReplayRequest, timeoutMs: number): Promise<ReplayExchange> {
2917	  return new Promise((resolve) => {
2918	    let settled = false;
2919	    const done = (outcome: ReplayExchange): void => {
2920	      if (!settled) {
2921	        settled = true;
2922	        clearTimeout(timer);
2923	        resolve(outcome);
2924	      }
2925	    };
2926	
2927	    // 业务头在前（原顺序/大小写/重复项），随后按目标与实际字节数重建
2928	    // Host 与 Content-Length；每条请求独立连接，响应结束后关闭。
2929	    const headers: string[] = [];
2930	    for (const [name, value] of request.headers) {
2931	      headers.push(name, value);
2932	    }
2933	    headers.push('Host', `127.0.0.1:${port}`);
2934	    headers.push('Content-Length', String(request.body.byteLength));
2935	    headers.push('Connection', 'close');
2936	
2937	    const req = http.request({
2938	      host: '127.0.0.1',
2939	      port,
2940	      method: request.method,
2941	      path: request.target, // 原样发送：保留查询串与百分号编码，不归一化
2942	      headers,
2943	      agent: false, // 不连接池化：一次一条，每条只尝试一次
2944	    });
2945	
2946	    // 总超时：覆盖连接建立与完整收发，持续来数据不延长
2947	    const timer = setTimeout(() => {
2948	      req.destroy();
2949	      done({ ok: false, reason: `超过总超时 ${timeoutMs}ms（自开始连接覆盖完整收发）` });
2950	    }, timeoutMs);
2951	
2952	    req.on('response', (res) => {
2953	      const chunks: Buffer[] = [];
2954	      res.on('data', (chunk: Buffer) => chunks.push(chunk));
2955	      res.on('end', () => {
2956	        done({
2957	          ok: true,
2958	          response: { status: res.statusCode ?? 0, body: Buffer.concat(chunks) },
2959	        });
2960	      });
2961	      res.on('aborted', () => {
2962	        done({ ok: false, reason: '响应中途断开（部分响应不算完整）' });
2963	      });
2964	      res.on('error', (e: unknown) => {
2965	        done({ ok: false, reason: `响应读取失败：${describeError(e)}` });
2966	      });
2967	      res.on('close', () => {
2968	        if (!res.complete) {
2969	          done({ ok: false, reason: '响应中途断开（部分响应不算完整）' });
2970	        }
2971	      });
2972	    });
2973	    req.on('error', (e: Error) => {
2974	      done({ ok: false, reason: `通信失败：${e.message}` });
2975	    });
2976	    req.end(request.body);
2977	  });
2978	}
