1	// 进程内请求记录的回归测试（真实本机服务 + 真实 HTTP/原始套接字请求）
2	//
3	// 覆盖：
4	// - 记录内容：方法、含查询串目标、原始请求头（含重复头）、正文原始字节
5	//   （合法 UTF-8 文本 / 非法 UTF-8 base64 无损）、接收时配置版本、匹配/校验结论、
6	//   400 实际差异报告、消费位置（末项复用记同一位置；400/404 无位置）、
7	//   计划响应（场景/框架：状态、应用层头含准确版本头、正文）；
8	// - 写出生命周期：延迟期间 pending → sent；写出前断开 interrupted（仍消费）；
9	// - 清空：移除当时全部记录（含 pending），不取消响应、不改变配置/版本/序列，
10	//   清空前完整接收的请求之后完成也不再出现；编号清空与重载后均不复用；
11	// - reload：成功/失败都保留记录；在途请求钉住旧版本与旧计划响应；后续请求用新版本；
12	// - 管理范围（/__contractlab 本身及 /__contractlab/ 前缀）不记录；查询不推进序列；
13	// - 未收完整即断开、超出正文上限（413）：不创建记录、不消费序列。
14	
15	import assert from 'node:assert/strict';
16	import http from 'node:http';
17	import net from 'node:net';
18	import test from 'node:test';
19	import { makeTempDir, startServer, writeConfig, type RunningServer } from './helpers.ts';
20	
21	const SLOW_DELAY = 400;
22	
23	function config(): unknown {
24	  return {
25	    endpoints: [
26	      {
27	        method: 'GET',
28	        path: '/api/seq',
29	        responses: [
30	          { status: 200, headers: { 'X-Item': 'one' }, body: 'one', delay: 0 },
31	          { status: 201, headers: { 'X-Item': 'two' }, body: 'two', delay: 0 },
32	          { status: 202, headers: { 'X-Item': 'last' }, body: 'last', delay: 0 },
33	        ],
34	      },
35	      {
36	        method: 'GET',
37	        path: '/api/slow',
38	        responses: [
39	          { status: 200, headers: {}, body: 'slow-one', delay: SLOW_DELAY },
40	          { status: 201, headers: {}, body: 'slow-two', delay: SLOW_DELAY },
41	        ],
42	      },
43	      {
44	        method: 'POST',
45	        path: '/api/echo',
46	        requestBody: {
47	          type: 'object',
48	          fields: { id: { type: 'integer', required: true } },
49	          additionalProperties: false,
50	        },
51	        responses: [{ status: 200, headers: {}, body: 'echo-ok', delay: 0 }],
52	      },
53	    ],
54	  };
55	}
56	
57	interface AdminReply {
58	  readonly status: number;
59	  readonly body: string;
60	}
61	
62	// 管理/普通请求：UTF-8 文本往返
63	function textRequest(
64	  port: number,
65	  method: string,
66	  path: string,
67	  body?: string,
68	  headers: Record<string, string> = {},
69	): Promise<{ status: number; headers: Record<string, string | string[]>; body: string }> {
70	  return new Promise((resolve, reject) => {
71	    const h: Record<string, string> = { ...headers };
72	    if (body !== undefined) {
73	      h['Content-Length'] = String(Buffer.byteLength(body));
74	    }
75	    const r = httpConnect(port, method, path, h, (res) => {
76	      let data = '';
77	      res.setEncoding('utf8');
78	      res.on('data', (d: string) => (data += d));
79	      res.on('end', () => resolve({ status: res.statusCode ?? 0, headers: res.headers, body: data }));
80	    });
81	    r.on('error', reject);
82	    if (body !== undefined) {
83	      r.write(body);
84	    }
85	    r.end();
86	  });
87	}
88	
89	function httpConnect(
90	  port: number,
91	  method: string,
92	  path: string,
93	  headers: Record<string, string>,
94	  cb: (res: http.IncomingMessage) => void,
95	): http.ClientRequest {
96	  return http.request({ host: '127.0.0.1', port, method, path, headers }, cb);
97	}
98	
99	async function clearRecords(port: number): Promise<AdminReply> {
100	  return textRequest(port, 'POST', '/__contractlab/requests/clear');
101	}
102	
103	interface WireRecord {
104	  readonly id: number;
105	  readonly receivedAt: string;
106	  readonly request: {
107	    readonly method: string;
108	    readonly target: string;
109	    readonly path: string;
110	    readonly rawHeaders: readonly string[];
111	    readonly bodyBytes: number;
112	    readonly body: { readonly encoding: string; readonly content: string };
113	  };
114	  readonly configVersion: number;
115	  readonly matched: boolean;
116	  readonly endpoint: string | null;
117	  readonly bodyValidationPassed: boolean | null;
118	  readonly bodyRejection: {
119	    readonly error: string;
120	    readonly stage: string;
121	    readonly message: string;
122	    readonly problems: readonly { readonly pointer: string; readonly expected: string; readonly actual: string }[];
123	  } | null;
124	  readonly sequencePosition: number | null;
125	  readonly sequenceLength: number | null;
126	  readonly plannedResponse: {
127	    readonly kind: string;
128	    readonly status: number;
129	    readonly headers: Record<string, string>;
130	    readonly body: string;
131	  } | null;
132	  readonly delivery: string;
133	}
134	
135	async function getRecords(port: number): Promise<WireRecord[]> {
136	  const reply = await textRequest(port, 'GET', '/__contractlab/requests');
137	  assert.equal(reply.status, 200);
138	  const parsed = JSON.parse(reply.body) as {
139	    note: string;
140	    count: number;
141	    records: WireRecord[];
142	  };
143	  assert.equal(typeof parsed.note, 'string');
144	  assert.ok(parsed.note.length > 0, '查询结果应附简短调用说明');
145	  assert.equal(parsed.count, parsed.records.length);
146	  return parsed.records;
147	}
148	
149	const sleep = (ms: number): Promise<void> => new Promise((r) => setTimeout(r, ms));
150	
151	// 原始套接字请求：用于重复头、非法 UTF-8、半途断开等 HTTP 客户端不便表达的场景
152	function rawWrite(port: number, raw: Buffer): Promise<net.Socket> {
153	  return new Promise((resolve, reject) => {
154	    const socket = net.connect(port, '127.0.0.1', () => {
155	      socket.write(raw);
156	      resolve(socket);
157	    });
158	    socket.on('error', reject);
159	  });
160	}
161	
162	async function rawRequest(port: number, raw: Buffer): Promise<{ status: number; socket: net.Socket; read: () => Promise<Buffer> }> {
163	  const socket = await rawWrite(port, raw);
164	  const readers: Buffer[] = [];
165	  let waitEnd: (() => void) | undefined;
166	  const onEnd = (): void => waitEnd?.();
167	  socket.on('data', (c) => readers.push(c));
168	  socket.on('end', onEnd);
169	  let peek: { status: number } | undefined;
170	  // 等待状态行到达
171	  for (let i = 0; i < 100 && !peek; i += 1) {
172	    if (readers.length > 0) {
173	      const head = Buffer.concat(readers).toString('latin1');
174	      const m = head.match(/^HTTP\/1\.\d (\d{3})/);
175	      if (m) {
176	        peek = { status: Number(m[1]) };
177	        break;
178	      }
179	    }
180	    await sleep(5);
181	  }
182	  assert.ok(peek, '应收到响应状态行');
183	  return {
184	    status: (peek as { status: number }).status,
185	    socket,
186	    read: async () =>
187	      new Promise<Buffer>((resolve) => {
188	        if (socket.destroyed || socket.readableEnded) {
189	          resolve(Buffer.concat(readers));
190	          return;
191	        }
192	        waitEnd = () => resolve(Buffer.concat(readers));
193	      }),
194	  };
195	}
