197	test('记录内容：场景响应、400 差异报告、404、末项复用位置与准确版本头', { timeout: 60_000 }, async (t) => {
198	  const dir = await makeTempDir(t);
199	  const file = await writeConfig(dir, 'scenes.json', config());
200	  const server: RunningServer = await startServer(file);
201	  t.after(server.close);
