653	test('超出正文上限：413、不创建记录、不消费序列', { timeout: 60_000 }, async (t) => {
654	  const dir = await makeTempDir(t);
655	  const file = await writeConfig(dir, 'scenes.json', config());
656	  const server = await startServer(file);
657	  t.after(server.close);
658	  const port = server.port;
659	  await clearRecords(port);
660	
661	  const limit = 100 * 1024 * 1024;
662	  const socket = net.connect(port, '127.0.0.1');
663	  await new Promise<void>((resolve) => socket.once('connect', resolve));
664	  socket.write(
665	    [
666	      'POST /api/echo HTTP/1.1',
667	      'Host: 127.0.0.1',
668	      'Content-Type: application/json',
669	      `Content-Length: ${limit + 1}`,
670	      '',
671	      '',
672	    ].join('\r\n'),
673	    'utf8',
674	  );
675	
676	  // 读到 413 即停止发送（复用缓冲区流式写入，避免持有两份百兆正文）
677	  const status = await new Promise<number>((resolve, reject) => {
678	    let head = '';
679	    const onData = (chunk: Buffer): void => {
680	      head += chunk.toString('latin1');
681	      const m = head.match(/^HTTP\/1\.\d (\d{3})/);
682	      if (m) {
683	        socket.pause();
684	        resolve(Number(m[1]));
685	      }
686	    };
687	    socket.on('data', onData);
688	    socket.on('error', reject);
689	
690	    const chunk = Buffer.alloc(64 * 1024, 0x61);
691	    let written = 0;
692	    const pump = (): void => {
693	      while (written <= limit) {
694	        const ready = socket.write(chunk);
695	        written += chunk.byteLength;
696	        if (!ready) {
697	          socket.once('drain', pump);
698	          return;
699	        }
700	      }
701	    };
702	    pump();
703	  });
704	  assert.equal(status, 413);
705	  socket.destroy();
