cd /tmp && mkdir -p cl-smoke && cat > cl-smoke/scenes.json <<'EOF'
{
  "endpoints": [
    {
      "method": "POST",
      "path": "/api/order",
      "requestBody": {
        "type": "object",
        "fields": {
          "kind": { "type": "string", "required": true },
          "n": { "type": "number" },
          "tags": { "type": "array", "items": { "type": "string" } }
        },
        "additionalProperties": true
      },
      "responses": [
        { "status": 200, "headers": { "X-Track": "fb0" }, "body": "fallback-0", "delay": 0 },
        { "status": 200, "headers": { "X-Track": "fb1" }, "body": "fallback-1", "delay": 0 }
      ],
      "branches": [
        {
          "id": "paid",
          "when": { "/kind": "paid" },
          "responses": [
            { "status": 201, "headers": { "X-Track": "p0" }, "body": "paid-0", "delay": 0 },
            { "status": 201, "headers": { "X-Track": "p1" }, "body": "paid-1", "delay": 0 }
          ]
        },
        {
          "id": "paid-high",
          "when": { "/kind": "paid", "/n": 10 },
          "responses": [
            { "status": 202, "headers": { "X-Track": "ph" }, "body": "paid-high", "delay": 0 }
          ]
        },
        {
          "id": "tag-first-a",
          "when": { "/tags/0": "a" },
          "responses": [
            { "status": 203, "headers": { "X-Track": "t" }, "body": "tag-a", "delay": 0 }
          ]
        },
        {
          "id": "root",
          "when": { "": null },
          "responses": [
            { "status": 205, "headers": {}, "body": "", "delay": 0 }
          ]
        }
      ]
    }
  ]
}
EOF
cd /Users/Shared/products-20261005/contractlab/a/task012
node app.ts serve -c /tmp/cl-smoke/scenes.json -p 0 > /tmp/cl-smoke/srv.log 2>&1 &
SRV=$!
sleep 1
cat /tmp/cl-smoke/srv.log
PORT=$(grep -oE '127.0.0.1:[0-9]+' /tmp/cl-smoke/srv.log | head -1 | cut -d: -f2)
echo "PORT=$PORT"
echo "--- paid (expect paid-0)"
curl -sS -H 'Content-Type: application/json' -d '{"kind":"paid"}' http://127.0.0.1:$PORT/api/order; echo
echo "--- paid n=10 (overlap -> first branch paid, expect paid-1)"
curl -sS -H 'Content-Type: application/json' -d '{"kind":"paid","n":10}' http://127.0.0.1:$PORT/api/order; echo
echo "--- tags a, kind other (expect tag-a)"
curl -sS -H 'Content-Type: application/json' -d '{"kind":"x","tags":["a"]}' http://127.0.0.1:$PORT/api/order; echo
echo "--- no match (expect fallback-0)"
curl -sS -H 'Content-Type: application/json' -d '{"kind":"other"}' http://127.0.0.1:$PORT/api/order; echo
echo "--- paid again (expect paid-0 last? paid seq had 0,1 then last=1 -> paid-1)"
curl -sS -H 'Content-Type: application/json' -d '{"kind":"paid"}' http://127.0.0.1:$PORT/api/order; echo
echo "--- missing kind field but condition null root never matches object; body invalid? additional props, kind required -> 400"
curl -sS -o /dev/null -w '%{http_code}\n' -H 'Content-Type: application/json' -d '{}' http://127.0.0.1:$PORT/api/order
kill $SRV 2>/dev/null

