        { "id": "a-null", "when": { "/a": null }, "responses": [ { "status": 203, "headers": {}, "body": "anull", "delay": 0 } ] },
        { "id": "zero", "when": { "/a": -0 }, "responses": [ { "status": 204, "headers": {}, "body": "", "delay": 0 } ] }
      ]
    },
    {
      "method": "POST",
