code(){ curl -sS -o /tmp/cl-smoke/body.out -w '%{http_code}' -H 'Content-Type: application/json' -d "$2" "http://127.0.0.1:$PORT$1"; echo " body=$(cat /tmp/cl-smoke/body.out)"; }
