    },
    {
      name: '空 id',
      config: {
        endpoints: [
          { method: 'POST', path: '/p', requestBody: okRule, responses: goodResponses, branches: [br('', { '': 1 }, goodResponses)] },
        ],
      },
      needle: '.id 必须是非空字符串',
    },
    {
      name: '空 when',
      config: {
        endpoints: [
          { method: 'POST', path: '/p', requestBody: okRule, responses: goodResponses, branches: [br('x', {}, goodResponses)] },
